"""Accurate publisher identity and visible authorship for the publication."""
from html import escape


def h(value):
    return escape(str(value), quote=True)


AUTHOR_PATH = '/authors/jennie-malone/'


def author_schema(origin):
    return {
        '@type': 'Person', '@id': origin + AUTHOR_PATH + '#person',
        'name': 'Jennie Malone', 'url': origin + AUTHOR_PATH,
        'jobTitle': 'Founder and publisher',
        'worksFor': {'@id': origin + '/#publisher'},
        'description': 'Founder of Seller Insider Hub, with a background in enterprise software engineering and ecommerce.'
    }


def byline(checked_at, minutes=None, published_at=None):
    parts = [f'<span>By <a rel="author" href="{AUTHOR_PATH}">Jennie Malone</a></span>']
    if published_at:
        parts.append(f'<span>Published <time datetime="{h(published_at)}">{h(published_at)}</time></span>')
    parts.append(f'<span>Sources checked <time datetime="{h(checked_at)}">{h(checked_at)}</time></span>')
    if minutes:
        parts.append(f'<span>{int(minutes)} min read</span>')
    return '<div class="article-byline"><span class="author-mark" aria-hidden="true">JM</span>' + ''.join(parts) + '</div>'


def author_note():
    return '''<aside class="author-note" aria-label="About the author and research method"><div class="author-note-heading"><span class="author-mark" aria-hidden="true">JM</span><div><strong><a rel="author" href="/authors/jennie-malone/">Jennie Malone</a></strong><span>Founder &amp; publisher, Seller Insider Hub</span></div></div><p>I built this publication to make useful technology understandable to small business owners. My background combines enterprise software engineering and ecommerce; the aim here is a decision you can explain and a workflow you can check.</p><p class="small">Research and drafting use AI assistance. Product instructions are based on the cited documentation unless the article identifies a hands-on demonstration. Worked examples and suggested tests are labelled; they are not customer results.</p><div class="actions"><a class="link" href="/editorial-standards/">How the research works →</a><a class="link" href="/corrections/">Report a correction →</a></div></aside>'''


def author_profile(plays, comparisons):
    stories = ''.join(f'<li><a href="/playbooks/{h(p["id"])}/">{h(p["title"])}</a></li>' for p in plays)
    choices = ''.join(f'<li><a href="/comparisons/{h(c["id"])}/">{h(c["title"])}</a></li>' for c in comparisons)
    return '''<div class="wrap simple-article"><div class="author-profile-intro"><span class="author-mark" aria-hidden="true">JM</span><p class="eyebrow">Founder &amp; publisher</p></div><h2>Useful technology should be understandable.</h2><p>I'm Jennie Malone, the founder of Seller Insider Hub. My background brings together enterprise software engineering and hands-on ecommerce. I previously worked on large business systems at Disney and later built and operated creative businesses of my own.</p><p>I built this publication for the owner who needs to finish a real job: prepare an accurate listing, deliver a welcome email, keep track of an inquiry, or understand what a software subscription will actually cover. The tutorials explain what goes into the workflow, what should come out, and how to spot a failure.</p><h2>What I cover</h2><p>AI assistants, small-business software, ecommerce workflows, email, content production, and practical automation. Seller Insider Hub serves sellers, creators, local and service businesses, and small teams. A reader should be able to use the instructions without booking a call or buying a service from me.</p><h2>How these articles are produced</h2><p>The publication uses AI assistance for research organization, drafting, and software development. Current product facts are checked against the cited vendor documentation. Articles explain the difference between documented capabilities, editorial judgments, synthetic examples, and any hands-on demonstrations. A byline identifies authorship and editorial responsibility; it does not mean every vendor has been personally tested.</p><p>My previous employment is background, not an endorsement of this publication by Disney. Seller Insider Hub is operated by The Local Upgrade LLC. The Local Upgrade provided the website's software development.</p><div class="actions"><a class="button light" href="/about/">Why I built the Hub</a><a class="button light" href="/editorial-standards/">Editorial standards</a><a class="button light" href="/contact/">Contact the publication</a></div><h2>Tutorials</h2><ul class="author-story-list">''' + stories + '</ul><h2>Software decisions</h2><ul class="author-story-list">' + choices + '</ul></div>'


def editorial_standards():
    return '''<div class="wrap simple-article"><p class="editorial-lede">My standard for a useful guide is simple: you should be able to explain the choice, follow the setup, recognize a good result, and recover when something goes wrong.</p><p>— <a rel="author" href="/authors/jennie-malone/">Jennie Malone</a>, founder and publisher</p><h2 id="responsibility">Who is responsible</h2><p>Seller Insider Hub is founded by Jennie Malone and operated by The Local Upgrade LLC. Articles carry Jennie's byline, with publication responsibility described on her author page. Background and previous employment are not vendor endorsements or evidence that a product has been tested.</p><h2 id="research">Research starts with a job to finish</h2><p>We use reader questions, relevant search observations, and official software documentation to choose useful coverage. A search result shows what that search returned; it is not a search-volume estimate. Articles stay within the publication's small-business focus and add a complete example, decision, or procedure beyond the source material.</p><h2 id="evidence">What the evidence labels mean</h2><div class="table-scroll"><table class="data-table"><thead><tr><th scope="col">Label</th><th scope="col">What it establishes</th><th scope="col">What it does not establish</th></tr></thead><tbody><tr><th scope="row">Official documentation reviewed</th><td>The cited provider describes the feature, price, limit, or procedure, checked on the stated date.</td><td>Independent reliability, output quality, or a completed account test.</td></tr><tr><th scope="row">Worked or illustrative example</th><td>A complete synthetic input, calculation, mapping, draft, or expected result that a reader can adapt.</td><td>A real customer's results, measured savings, or an actual sent message.</td></tr><tr><th scope="row">Vendor screenshot</th><td>A labelled image from a named vendor's documentation, with its original source.</td><td>A screenshot of our account or proof we completed that workflow.</td></tr><tr><th scope="row">Hands-on demonstration</th><td>A specifically identified activity, with the actual environment, procedure, and evidence available in that article.</td><td>Performance in other accounts or a general ranking of competing products.</td></tr><tr><th scope="row">Recommendation</th><td>Editorial judgment about a stated use case, supported by the documented requirements and tradeoffs.</td><td>A guarantee of sales, traffic, savings, suitability, or a vendor's future behavior.</td></tr></tbody></table></div><h2 id="tutorials">What belongs in a complete tutorial</h2><ul><li>A concrete outcome and the situations where the workflow does not fit.</li><li>Prerequisites, account permissions, plan restrictions, and a simpler alternative when one works.</li><li>Filled example inputs, field mappings, prompts, or templates readers can reuse.</li><li>Source-supported steps and expected intermediate results.</li><li>Checks for the normal case, missing information, repeat submissions, and failures where relevant.</li><li>A way to pause, recover, and maintain the workflow.</li><li>Sources, dates, cost assumptions, and clear limits on what has been verified.</li></ul><h2 id="comparisons">How comparisons and cost tools work</h2><p>We compare the job and its constraints: subscriber counts, email sends, channels, brands, seats, actions, or credits as applicable. Monthly payments, annual prepayments, and monthly equivalents are shown separately. Unknown prices are not counted as zero. A verified plan band is not extrapolated to a larger account.</p><p>Calculators apply disclosed arithmetic to public plan facts. They do not measure the quality of AI responses or guarantee an entire stack's cost. Suggested trial tasks are a way for you to evaluate fit; they are not presented as tests we have already run. We do not publish invented star ratings or unmeasured performance scores.</p><h2 id="ai">How AI is used</h2><p>AI assists with research organization, drafting, examples, and website development. It is useful for connecting documentation across tools and preparing reusable instructions. It is not a source of truth. We check current claims against primary sources, label synthetic examples, and avoid invented experiences, credentials, testimonials, or customer outcomes.</p><p>Substantial articles disclose this method through their author and research notes. AI-generated illustrations or avatars are identified where used. Product screenshots come from the stated vendor source or an identified actual demonstration; an invented interface is not used as evidence.</p><h2 id="independence">How money affects coverage</h2><p>Some links may earn a commission when a reader buys. That possibility does not determine the recommended workflow or entitle a vendor to a favorable conclusion. We include suitable products without affiliate programs, free plans, native features, and reasons to buy nothing. Any paid placement must be labelled. See the <a href="/legal/affiliate-disclosure/">affiliate disclosure</a>.</p><h2 id="updates">Dates and corrections</h2><p>Published dates describe publication, source-check dates describe the research, and updated dates describe material changes. Rebuilding the website is not a reason to make an old article look newly researched. We revisit guidance when a cited price, plan, policy, or procedure changes or a reader identifies a specific error.</p><p>Report the page, the disputed claim, and any supporting source through the <a href="/corrections/">corrections page</a>. A source-check date is not a promise that a vendor's documentation will remain unchanged.</p><h2 id="privacy">Respect for readers</h2><p>Tutorial kits and on-page decision tools are available without a consultation. Saved checklists and reading lists are stored in your browser; private inputs are not sent to analytics. Optional analytics follows the choice in Cookie preferences. Our <a href="/legal/privacy/">privacy policy</a> describes the site's actual data handling.</p></div>'''


def corrections_page():
    return '''<div class="wrap simple-article"><p>A useful correction identifies something another reader could get wrong. If a plan limit changed, a step no longer matches the product, or a calculation is wrong, please send the page URL and the specific issue.</p><h2>What to include</h2><ul><li>The Seller Insider Hub page and section.</li><li>The claim or step that needs checking.</li><li>A current official source, if you have one.</li><li>The relevant product plan and region, when they affect the answer.</li></ul><p>Do not include passwords, API keys, customer records, or private screenshots. A redacted description is enough to begin checking.</p><a class="button" href="/contact/">Send a correction →</a><h2>How updates are handled</h2><p>Errors that affect a buying decision, permission, bill, or customer-facing action take priority. A substantive correction should explain what changed in the article's update note. Small spelling or layout changes do not imply new product research. There is no promised response time.</p><p>Jennie Malone is the publication's accountable publisher. The <a href="/editorial-standards/">editorial standards</a> explain source checking, examples, screenshots, and the use of AI.</p></div>'''
